update public.lessons
set duration_seconds = 405,
    content_blocks = '{"blocks": [{"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_01.mp3"], "total_audio_seconds": 58.76, "timed_text": [{"start_s": 1.32, "text": "Day 6."}, {"start_s": 6.58, "text": "Anxiety shows up in your body before it shows up in your thoughts."}, {"start_s": 10.7, "text": "Tight jaw. Raised shoulders. Clenched fists. Shallow breathing."}, {"start_s": 16.16, "text": "You''ve felt all of it before a big competition."}, {"start_s": 21.96, "text": "Today we fix that."}, {"start_s": 23.88, "text": "We''re going to scan your body from head to toe."}, {"start_s": 35.22, "text": "This teaches you to read your own nervous system in real time."}, {"start_s": 48.46, "text": "Before we start — take one box breath with me."}]}, {"type": "timed_exercise", "duration_seconds": 16, "interactive_model": "box_breathing", "visual_cues": ["One full breath. Settle in.", "Follow the circle."], "steps": [{"text": "Inhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}, {"text": "Exhale", "duration_seconds": 4, "haptic": "heavy"}, {"text": "Hold", "duration_seconds": 4, "haptic": "light"}]}, {"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_02.mp3"], "total_audio_seconds": 246.22, "timed_text": [{"start_s": 3.66, "text": "Good. Close your eyes."}, {"start_s": 6.04, "text": "We''re moving from the top of your head down to your feet."}, {"start_s": 24.66, "text": "Top of your head. Your forehead. Your eyes."}, {"start_s": 71.62, "text": "Is there tension here? Breathe in — and release it on the exhale."}, {"start_s": 129.55, "text": "Your jaw. Your neck. Your throat."}, {"start_s": 155.75, "text": "Athletes carry a lot here. Breathe in — let it soften."}, {"start_s": 169.76, "text": "Your shoulders. Your upper back."}, {"start_s": 192.76, "text": "Are they raised right now? Drop them. One slow breath in — and release."}, {"start_s": 210.7, "text": "Your chest. Your lungs. Let the breath go all the way down."}, {"start_s": 235.02, "text": "Your arms. Your hands. Your fingers. Unclench."}, {"start_s": 238.5, "text": "Your core. Your stomach. This is where nerves live. Breathe into it. Let it expand."}, {"start_s": 242.0, "text": "Your hips. Your legs. Your feet. All the way to the floor."}, {"start_s": 245.0, "text": "Now — whole body. One full breath in. Feel everything you just released. And exhale. Let it all go."}]}, {"type": "voiceover", "audio_files": ["lesson_06/lesson_06_seg_03.mp3"], "total_audio_seconds": 24.32, "timed_text": [{"start_s": 0.66, "text": "Open your eyes."}, {"start_s": 3.02, "text": "You just learned how to read your nervous system and reset it in under two minutes."}, {"start_s": 14.26, "text": "Aware athletes don''t get blindsided by their own bodies."}, {"start_s": 20.44, "text": "Go hit the journal."}]}, {"type": "journal_prompt", "prompt": "Where did your body hold the most tension? Does that same spot show up when you compete?"}]}'::jsonb,
    updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000006';

